import{_ as n,l as r,o as e,c as d,v as o,p as s,x as t,d as i,i as c,S as L}from"./chunks/framework.InCnrqk-.js";const U=JSON.parse('{"title":"空值与三值逻辑","description":"","frontmatter":{"title":"空值与三值逻辑","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sql-null.md","filePath":"cs/sql-null.md","lastUpdated":1789023840000}'),p={name:"cs/sql-null.md"};function h(u,a,E,_,N,m){const l=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="空值与三值逻辑" tabindex="-1">空值与三值逻辑 <a class="header-anchor" href="#空值与三值逻辑" aria-label="Permalink to &quot;空值与三值逻辑&quot;">​</a></h1><div class="epigraph"><p>NULL 不是域里的值；谓词遇上它得到 unknown，WHERE 只留真，于是同一表达式不再总服从集合代数的直觉。</p><footer>—— 据 Date 对缺失信息的批评；SQL 标准三值逻辑；Codd 后来的标记方案对照</footer></div><p><a href="/cs/sql-declarative">上一课</a>把查询写成声明：含义应对准代数。本课不重写 SELECT。缺口是 SQL 允许缺失：外键置空、未填列。若把 NULL 当普通值，相等与连接会把「不知道」当成匹配或当成不等，两种都会错。三值逻辑是工程合同，不是关系模型 1970 的一部分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/relational-model">关系模型</a> 的域里每个属性有值。SQL 增加 NULL。比较结果是 true / false / unknown；<code>WHERE</code> 与 <code>HAVING</code> 保留 true。<code>NOT unknown</code> 仍是 unknown。连接在 NULL 上不匹配。缺口是<strong>声明语义相对集合代数的缝</strong>，以便后课连接算法不要把 NULL 当哈希键上的普通字节就完事。</p><p><span class="marginnote">Date 主张避免 NULL。主干承认 SQL 有它，并用三值把坑钉死：<code>x = x</code> 在 x 为 NULL 时不是真；<code>UNIQUE</code> 对多 NULL 的行为按标准版本而异。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>求值：算术与比较遇 NULL 变 unknown（除少数 <code>IS NULL</code>）。聚合默认跳过 NULL，<code>COUNT(*)</code> 例外。外连接用 NULL 填不成配的一侧——这是有意的标记，不是「零」。本课不把全部标准边角写成百科。</p>',8)),(e(),s(L,null,{default:t(()=>[c(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20TV%5B%22%E7%9C%9F%20%2F%20%E5%81%87%20%2F%20%E6%9C%AA%E7%9F%A5%22%5D%0A%20%20TV%20--%3E%20W%5B%22WHERE%20%E5%8F%AA%E7%95%99%E7%9C%9F%22%5D%0A%20%20NULL%5B%22NULL%20%E5%8F%82%E4%B8%8E%E6%AF%94%E8%BE%83%22%5D%20--%3E%20UNK%5B%22%E6%9C%AA%E7%9F%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三值使优化器的某些代数律失效：选择下推遇到 NULL 与外连接时要检查。哈希连接把 NULL 当不相等，嵌套循环同样。完整性：主键不允许 NULL；外键列可空是<a href="/cs/fk-actions">参照动作</a> 置空的前提。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入第四种逻辑或 Codd 的 A/I 标记当主干。物理上连接怎么扫表，下一课连接算法总览。</p><p>后课默认：SQL 结果按三值过滤。同一逻辑连接仍有多种物理算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NULL 产生 unknown；WHERE 不留未知。</li><li>部分代数律在 SQL 里要加条件。</li><li>连接的物理实现下一课。</li><li>出处：SQL 三值逻辑；Date；对照 Codd。</li></ul>',7))])}const A=n(p,[["render",h]]);export{U as __pageData,A as default};
